changeSet.sql:
create table job_positions ( id bigint generated always as identity primary key, organization_id bigint not null, title varchar(255) not null, location varchar(255), employment_type varchar(255), description_html text, short_description text, active boolean not null default true, sort integer not null default 0, created_at timestamptz not null default now() );
create index job_positions_organization_id_idx on job_positions (organization_id);
create table job_applications ( id bigint generated always as identity primary key, organization_id bigint not null, job_position_id bigint, name varchar(255) not null, email varchar(255) not null, phone varchar(50), message text, cv_path varchar(255), cv_original_name varchar(255), is_read boolean not null default false, status varchar(20) not null default 'pending', future_recruitment_consent boolean not null default false, future_recruitment_consent_at timestamptz, created_at timestamptz not null default now() );
create index job_applications_organization_id_idx on job_applications (organization_id); create index job_applications_job_position_id_idx on job_applications (job_position_id); create index job_applications_status_idx on job_applications (status); create index job_applications_future_consent_idx on job_applications (future_recruitment_consent);
